93	    let max_messages = std::env::var("XMPP_BRIDGE_MAX_MESSAGES")
94	        .ok()
95	        .and_then(|value| value.parse::<usize>().ok())
96	        .filter(|value| *value > 0)
97	        .unwrap_or(DEFAULT_MAX_MESSAGES);
