123	async fn configure_handler(
124	    ConnectInfo(remote): ConnectInfo<SocketAddr>,
125	    State(state): State<AppState>,
126	    headers: HeaderMap,
127	    Json(request): Json<ConfigureRequest>,
128	) -> Result<Json<ConfigureResponse>, BridgeError> {
129	    authorize(&state, &headers, remote)?;
130	
131	    let normalized = normalize_config(&request)?;
132	
133	    {
134	        let inner = state.inner.read().await;
135	        if let Some(existing) = inner.configured.as_ref() {
136	            if existing == &normalized {
137	                return Ok(Json(ConfigureResponse {
138	                    configured: true,
139	                    running: inner.channel.is_some(),
140	                    jid: inner.jid.clone().unwrap_or_else(|| normalized.jid.clone()),
141	                }));
142	            }
143	            return Err(BridgeError::conflict(
144	                "xmpp-bridge is already configured; restart it to apply a different config",
145	            ));
146	        }
147	    }
148	
149	    let native_config = to_native_config(&normalized);
150	    let channel = Arc::new(XmppChannel::new(native_config).await.map_err(|e| {
151	        BridgeError::bad_gateway(&format!("failed to initialize XMPP client: {}", e))
152	    })?);
153	    let mut stream = channel
154	        .start()
155	        .await
156	        .map_err(|e| BridgeError::bad_gateway(&format!("failed to start XMPP client: {}", e)))?;
157	
158	    {
159	        let mut inner = state.inner.write().await;
160	        inner.configured = Some(normalized.clone());
161	        inner.jid = Some(normalized.jid.clone());
162	        inner.channel = Some(Arc::clone(&channel));
163	    }
164	
165	    let state_for_task = state.clone();
166	    tokio::spawn(async move {
167	        while let Some(message) = stream.next().await {
168	            enqueue_message(&state_for_task, message).await;
169	        }
170	        tracing::warn!("xmpp-bridge input stream ended");
171	    });
172	
173	    Ok(Json(ConfigureResponse {
174	        configured: true,
175	        running: true,
176	        jid: normalized.jid,
177	    }))
178	}
