180	async fn status_handler(
181	    ConnectInfo(remote): ConnectInfo<SocketAddr>,
182	    State(state): State<AppState>,
183	    headers: HeaderMap,
184	) -> Result<Json<BridgeStatusResponse>, BridgeError> {
185	    authorize(&state, &headers, remote)?;
186	
187	    let (
188	        configured,
189	        running,
190	        current_cursor,
191	        queued_messages,
192	        jid,
193	        configured_rooms,
194	        configured_limit,
195	        channel,
196	    ) = {
197	        let inner = state.inner.read().await;
198	        (
199	            inner.configured.is_some(),
200	            inner.channel.is_some(),
201	            inner.current_cursor,
202	            inner.messages.len(),
203	            inner.jid.clone(),
204	            inner
205	                .configured
206	                .as_ref()
207	                .map(|config| config.allow_rooms.clone())
208	                .unwrap_or_default(),
209	            inner
210	                .configured
211	                .as_ref()
212	                .map(|config| config.max_messages_per_hour)
213	                .unwrap_or(0),
214	            inner.channel.clone(),
215	        )
216	    };
217	
218	    let diagnostics = if let Some(channel) = channel.as_ref() {
219	        Some(channel.omemo_diagnostics().await)
220	    } else {
221	        None
222	    };
223	    let presence_diagnostics = if let Some(channel) = channel.as_ref() {
224	        Some(channel.muc_presence_diagnostics().await)
225	    } else {
226	        None
227	    };
228	    let room_diagnostics = if let Some(channel) = channel.as_ref() {
229	        Some(channel.muc_encryption_diagnostics().await)
230	    } else {
231	        None
232	    };
233	    let outbound_rate_limit = if let Some(channel) = channel.as_ref() {
234	        Some(channel.outbound_rate_limit_diagnostics().await)
235	    } else {
236	        None
237	    };
238	    let active_limit = outbound_rate_limit
239	        .as_ref()
240	        .map(|value| value.max_messages_per_hour)
241	        .unwrap_or(configured_limit);
242	    let outbound_messages_last_hour = outbound_rate_limit
243	        .as_ref()
244	        .map(|value| value.messages_in_current_window)
245	        .unwrap_or(0);
246	
247	    Ok(Json(BridgeStatusResponse {
248	        configured,
249	        running,
250	        current_cursor,
251	        queued_messages,
252	        jid,
253	        configured_rooms,
254	        rooms_with_presence: presence_diagnostics
255	            .map(|value| value.rooms_with_presence)
256	            .unwrap_or_default(),
257	        configured_max_messages_per_hour: configured_limit,
258	        active_max_messages_per_hour: active_limit,
259	        outbound_messages_last_hour,
260	        outbound_rate_limit_overridden: active_limit != configured_limit,
261	        omemo_enabled: diagnostics
262	            .as_ref()
263	            .is_some_and(|value| value.omemo_enabled),
264	        device_id: diagnostics.as_ref().and_then(|value| value.device_id),
265	        fingerprint: diagnostics
266	            .as_ref()
267	            .and_then(|value| value.fingerprint.clone()),
268	        bundle_published: diagnostics
269	            .as_ref()
270	            .is_some_and(|value| value.bundle_published),
271	        prekeys_available: diagnostics
272	            .as_ref()
273	            .map(|value| value.prekeys_available)
274	            .unwrap_or(0),
275	        migration_state: diagnostics
276	            .as_ref()
277	            .map(|value| value.migration_state.clone()),
278	        last_omemo_error: diagnostics.and_then(|value| value.last_omemo_error),
279	        encrypted_rooms_total: room_diagnostics
280	            .as_ref()
281	            .map(|value| value.encrypted_rooms_total)
282	            .unwrap_or(0),
283	        encrypted_rooms_ready: room_diagnostics
284	            .as_ref()
285	            .map(|value| value.encrypted_rooms_ready)
286	            .unwrap_or(0),
287	        last_room_error: room_diagnostics.and_then(|value| value.last_room_error),
288	    }))
289	}
