291	async fn outbound_rate_limit_handler(
292	    ConnectInfo(remote): ConnectInfo<SocketAddr>,
293	    State(state): State<AppState>,
294	    headers: HeaderMap,
295	    Json(request): Json<OutboundRateLimitRequest>,
296	) -> Result<Json<OutboundRateLimitResponse>, BridgeError> {
297	    authorize(&state, &headers, remote)?;
298	
299	    let (configured, configured_limit, channel) = {
300	        let inner = state.inner.read().await;
301	        (
302	            inner.configured.is_some(),
303	            inner
304	                .configured
305	                .as_ref()
306	                .map(|config| config.max_messages_per_hour)
307	                .unwrap_or(0),
308	            inner.channel.clone(),
309	        )
310	    };
311	
312	    let channel =
313	        channel.ok_or_else(|| BridgeError::conflict("xmpp-bridge is not configured yet"))?;
314	    let current = channel.outbound_rate_limit_diagnostics().await;
315	    let next_limit = request
316	        .max_messages_per_hour
317	        .unwrap_or(current.max_messages_per_hour);
318	    let updated = channel
319	        .set_outbound_rate_limit(next_limit, request.reset_counter)
320	        .await;
321	
322	    tracing::info!(
323	        configured_max_messages_per_hour = configured_limit,
324	        active_max_messages_per_hour = updated.max_messages_per_hour,
325	        outbound_messages_last_hour = updated.messages_in_current_window,
326	        reset_counter = request.reset_counter,
327	        "Updated live XMPP outbound rate limit"
328	    );
329	
330	    Ok(Json(OutboundRateLimitResponse {
331	        configured,
332	        running: true,
333	        configured_max_messages_per_hour: configured_limit,
334	        active_max_messages_per_hour: updated.max_messages_per_hour,
335	        outbound_messages_last_hour: updated.messages_in_current_window,
336	        reset_counter_applied: request.reset_counter,
337	    }))
338	}
