340	async fn messages_handler(
341	    ConnectInfo(remote): ConnectInfo<SocketAddr>,
342	    State(state): State<AppState>,
343	    headers: HeaderMap,
344	    Query(query): Query<MessagesQuery>,
345	) -> Result<Json<MessagesResponse>, BridgeError> {
346	    authorize(&state, &headers, remote)?;
347	
348	    let cursor = query.cursor.unwrap_or(0);
349	    let inner = state.inner.read().await;
350	    let messages = inner
351	        .messages
352	        .iter()
353	        .filter(|message| message.cursor > cursor)
354	        .map(|message| message.payload.clone())
355	        .collect();
356	
357	    Ok(Json(MessagesResponse {
358	        cursor: inner.current_cursor,
359	        messages,
360	    }))
361	}
