363	async fn send_handler(
364	    ConnectInfo(remote): ConnectInfo<SocketAddr>,
365	    State(state): State<AppState>,
366	    headers: HeaderMap,
367	    Json(request): Json<SendRequest>,
368	) -> Result<Json<serde_json::Value>, BridgeError> {
369	    authorize(&state, &headers, remote)?;
370	
371	    let metadata: serde_json::Value = serde_json::from_str(&request.metadata_json)
372	        .map_err(|e| BridgeError::bad_request(&format!("invalid metadata_json: {}", e)))?;
373	
374	    let channel = {
375	        let inner = state.inner.read().await;
376	        inner.channel.clone()
377	    }
378	    .ok_or_else(|| BridgeError::conflict("xmpp-bridge is not configured yet"))?;
379	
380	    let mut response = OutgoingResponse::text(request.content);
381	    response.metadata = metadata;
382	
383	    channel
384	        .broadcast(&request.target, response)
385	        .await
386	        .map_err(|e| BridgeError::bad_gateway(&format!("failed to send XMPP message: {}", e)))?;
387	
388	    Ok(Json(serde_json::json!({ "ok": true })))
389	}
