391	async fn enqueue_message(state: &AppState, message: IncomingMessage) {
392	    let metadata_json =
393	        serde_json::to_string(&message.metadata).unwrap_or_else(|_| "{}".to_string());
394	    let payload = BridgeMessage {
395	        message_id: message.id.to_string(),
396	        user_id: message.user_id,
397	        user_name: message.user_name,
398	        content: message.content,
399	        thread_id: message.thread_id,
400	        metadata_json,
401	    };
402	
403	    let mut inner = state.inner.write().await;
404	    inner.current_cursor = inner.current_cursor.saturating_add(1);
405	    let cursor = inner.current_cursor;
406	    inner.messages.push_back(QueuedMessage { cursor, payload });
407	    while inner.messages.len() > state.max_messages {
408	        inner.messages.pop_front();
409	    }
410	}
