412	fn authorize(state: &AppState, headers: &HeaderMap, remote: SocketAddr) -> Result<(), BridgeError> {
413	    if !remote.ip().is_loopback() {
414	        return Err(BridgeError::forbidden(
415	            "xmpp-bridge only accepts loopback clients",
416	        ));
417	    }
418	
419	    let Some(expected_token) = state.expected_token.as_deref() else {
420	        return Ok(());
421	    };
422	
423	    let header = headers
424	        .get(axum::http::header::AUTHORIZATION)
425	        .and_then(|value| value.to_str().ok())
426	        .ok_or_else(|| BridgeError::unauthorized("missing Authorization header"))?;
427	
428	    let provided = header
429	        .strip_prefix("Bearer ")
430	        .or_else(|| header.strip_prefix("bearer "))
431	        .ok_or_else(|| BridgeError::unauthorized("Authorization header must use Bearer auth"))?;
432	
433	    if provided != expected_token {
434	        return Err(BridgeError::unauthorized("invalid bridge token"));
435	    }
436	
437	    Ok(())
438	}
