440	fn normalize_config(request: &ConfigureRequest) -> Result<NormalizedConfig, BridgeError> {
441	    let jid = request.jid.trim();
442	    if jid.is_empty() {
443	        return Err(BridgeError::bad_request("jid is required"));
444	    }
445	    let password = request.password.trim();
446	    if password.is_empty() {
447	        return Err(BridgeError::bad_request("password is required"));
448	    }
449	
450	    let resource = request
451	        .resource
452	        .as_deref()
453	        .map(str::trim)
454	        .filter(|value| !value.is_empty());
455	    let jid = if jid.contains('/') || resource.is_none() {
456	        jid.to_string()
457	    } else {
458	        format!("{}/{}", jid, resource.unwrap_or_default())
459	    };
460	
461	    let omemo_store_dir = request
462	        .omemo_store_dir
463	        .as_deref()
464	        .map(str::trim)
465	        .filter(|value| !value.is_empty())
466	        .map(PathBuf::from)
467	        .unwrap_or_else(|| ironclaw_base_dir().join("xmpp"));
468	
469	    Ok(NormalizedConfig {
470	        jid,
471	        password: password.to_string(),
472	        dm_policy: normalize_policy(&request.dm_policy),
473	        allow_from: normalize_list(&request.allow_from),
474	        allow_rooms: {
475	            let mut rooms = normalize_list(&request.allow_rooms);
476	            let encrypted_rooms = normalize_list(&request.encrypted_rooms);
477	            if !rooms.iter().any(|room| room == "*") {
478	                for room in &encrypted_rooms {
479	                    if !rooms
480	                        .iter()
481	                        .any(|value: &String| value.eq_ignore_ascii_case(room))
482	                    {
483	                        rooms.push(room.clone());
484	                    }
485	                }
486	            }
487	            rooms
488	        },
489	        encrypted_rooms: normalize_list(&request.encrypted_rooms),
490	        device_id: request.device_id,
491	        omemo_store_dir,
492	        allow_plaintext_fallback: request.allow_plaintext_fallback,
493	        max_messages_per_hour: request.max_messages_per_hour,
494	    })
495	}
