497	fn to_native_config(config: &NormalizedConfig) -> XmppConfig {
498	    XmppConfig {
499	        jid: config.jid.clone(),
500	        password: SecretString::from(config.password.clone()),
501	        allow_from: config.allow_from.clone(),
502	        dm_policy: config.dm_policy.clone(),
503	        allow_rooms: config.allow_rooms.clone(),
504	        encrypted_rooms: config.encrypted_rooms.clone(),
505	        device_id: config.device_id,
506	        omemo_store_dir: config.omemo_store_dir.clone(),
507	        allow_plaintext_fallback: config.allow_plaintext_fallback,
508	        max_messages_per_hour: config.max_messages_per_hour,
509	    }
510	}
511	
512	fn normalize_policy(policy: &str) -> String {
513	    let normalized = policy.trim().to_ascii_lowercase();
514	    if normalized.is_empty() {
515	        "allowlist".to_string()
516	    } else {
517	        normalized
518	    }
519	}
520	
521	fn normalize_list(values: &[String]) -> Vec<String> {
522	    values
523	        .iter()
524	        .map(|value| value.trim().to_string())
525	        .filter(|value| !value.is_empty())
526	        .collect()
527	}
