529	struct BridgeError {
530	    status: StatusCode,
531	    message: String,
532	}
533	
534	impl BridgeError {
535	    fn bad_request(message: &str) -> Self {
536	        Self {
537	            status: StatusCode::BAD_REQUEST,
538	            message: message.to_string(),
539	        }
540	    }
541	
542	    fn unauthorized(message: &str) -> Self {
543	        Self {
544	            status: StatusCode::UNAUTHORIZED,
545	            message: message.to_string(),
546	        }
547	    }
548	
549	    fn forbidden(message: &str) -> Self {
550	        Self {
551	            status: StatusCode::FORBIDDEN,
552	            message: message.to_string(),
553	        }
554	    }
555	
556	    fn conflict(message: &str) -> Self {
557	        Self {
558	            status: StatusCode::CONFLICT,
559	            message: message.to_string(),
560	        }
561	    }
562	
563	    fn bad_gateway(message: &str) -> Self {
564	        Self {
565	            status: StatusCode::BAD_GATEWAY,
566	            message: message.to_string(),
567	        }
568	    }
569	}
570	
571	impl IntoResponse for BridgeError {
572	    fn into_response(self) -> axum::response::Response {
573	        (
574	            self.status,
575	            Json(serde_json::json!({
576	                "error": self.message,
577	            })),
578	        )
579	            .into_response()
580	    }
581	}
