63	/// Format a top-level error with color and recovery hints.
64	fn format_top_level_error(err: &anyhow::Error) {
65	    use ironclaw::cli::fmt;
66	    let msg = format!("{err:#}");
67	
68	    eprintln!();
69	    eprintln!("  {}\u{2717}{} {}", fmt::error(), fmt::reset(), msg);
70	
71	    // Provide recovery hints for common errors
72	    let lower = msg.to_ascii_lowercase();
73	    let hint = if lower.contains("database_url")
74	        || lower.contains("database") && lower.contains("not set")
75	    {
76	        Some("run `ironclaw onboard` or set DATABASE_URL in .env")
77	    } else if lower.contains("connection refused") || lower.contains("connect error") {
78	        Some("check that the database server is running")
79	    } else if lower.contains("session") && lower.contains("not found") {
80	        Some("run `ironclaw onboard` to set up authentication")
81	    } else if lower.contains("secrets_master_key") {
82	        Some("run `ironclaw onboard` or set SECRETS_MASTER_KEY in .env")
83	    } else if lower.contains("already running") {
84	        Some("stop the other instance or remove the stale PID file")
85	    } else if lower.contains("onboard") {
86	        Some("run `ironclaw onboard` to complete setup")
87	    } else {
88	        None
89	    };
90	
91	    if let Some(hint_text) = hint {
92	        eprintln!("  {}hint:{} {}", fmt::dim(), fmt::reset(), hint_text,);
93	    }
94	    eprintln!();
95	}
