198	fn check(name: &str, result: CheckResult, passed: &mut u32, failed: &mut u32, skipped: &mut u32) {
199	    match result {
200	        CheckResult::Pass(detail) => {
201	            *passed += 1;
202	            println!(
203	                "{}",
204	                fmt::check_line(fmt::StatusKind::Pass, name, &detail, 18)
205	            );
206	        }
207	        CheckResult::Fail(detail) => {
208	            *failed += 1;
209	            println!(
210	                "{}",
211	                fmt::check_line(fmt::StatusKind::Fail, name, &detail, 18)
212	            );
213	        }
214	        CheckResult::Skip(reason) => {
215	            *skipped += 1;
216	            println!(
217	                "{}",
218	                fmt::check_line(fmt::StatusKind::Skip, name, &reason, 18)
219	            );
220	        }
221	    }
222	}
