231	
232	fn check_settings_file() -> CheckResult {
233	    let path = Settings::default_path();
234	    if !path.exists() {
235	        return CheckResult::Pass("no settings file (defaults will be used)".into());
236	    }
237	
238	    match std::fs::read_to_string(&path) {
239	        Ok(data) => match serde_json::from_str::<serde_json::Value>(&data) {
240	            Ok(_) => CheckResult::Pass(format!("valid ({})", path.display())),
241	            Err(e) => CheckResult::Fail(format!(
242	                "settings.json is malformed: {}. Fix or delete {}",
243	                e,
244	                path.display()
245	            )),
246	        },
247	        Err(e) => CheckResult::Fail(format!("cannot read {}: {}", path.display(), e)),
248	    }
249	}
