252	
253	async fn check_nearai_session(settings: &Settings) -> CheckResult {
254	    // Skip entirely when the configured backend is not NEAR AI.
255	    let llm_config = match crate::config::LlmConfig::resolve(settings) {
256	        Ok(config) => config,
257	        Err(e) => {
258	            // check_llm_config will report the full error; just skip here.
259	            return CheckResult::Skip(format!("LLM config error: {e}"));
260	        }
261	    };
262	    if llm_config.backend != "nearai" {
263	        return CheckResult::Skip(format!(
264	            "not using NEAR AI backend (backend={})",
265	            llm_config.backend
266	        ));
267	    }
268	
269	    // Check if session file exists
270	    let session_path = crate::config::llm::default_session_path();
271	    if !session_path.exists() {
272	        // Check for API key mode
273	        if crate::config::helpers::env_or_override("NEARAI_API_KEY").is_some() {
274	            return CheckResult::Pass("API key configured".into());
275	        }
276	        return CheckResult::Fail(format!(
277	            "session file not found at {}. Run `ironclaw onboard`",
278	            session_path.display()
279	        ));
280	    }
281	
282	    // Verify the session file is readable and non-empty
283	    match std::fs::read_to_string(&session_path) {
284	        Ok(content) if content.trim().is_empty() => {
285	            CheckResult::Fail("session file is empty".into())
286	        }
287	        Ok(_) => CheckResult::Pass(format!("session found ({})", session_path.display())),
288	        Err(e) => CheckResult::Fail(format!("cannot read session file: {e}")),
289	    }
290	}
