313	async fn check_database() -> CheckResult {
314	    let backend = std::env::var("DATABASE_BACKEND")
315	        .ok()
316	        .unwrap_or_else(|| "postgres".into());
317	
318	    match backend.as_str() {
319	        "libsql" | "turso" | "sqlite" => {
320	            let path = std::env::var("LIBSQL_PATH")
321	                .map(PathBuf::from)
322	                .unwrap_or_else(|_| crate::config::default_libsql_path());
323	
324	            if path.exists() {
325	                CheckResult::Pass(format!("libSQL database exists ({})", path.display()))
326	            } else {
327	                CheckResult::Pass(format!(
328	                    "libSQL database not found at {} (will be created on first run)",
329	                    path.display()
330	                ))
331	            }
332	        }
333	        _ => {
334	            if std::env::var("DATABASE_URL").is_ok() {
335	                // Try to connect
336	                match try_pg_connect().await {
337	                    Ok(()) => CheckResult::Pass("PostgreSQL connected".into()),
338	                    Err(e) => CheckResult::Fail(format!("PostgreSQL connection failed: {e}")),
339	                }
340	            } else {
341	                CheckResult::Fail("DATABASE_URL not set".into())
342	            }
343	        }
344	    }
345	}
