348	async fn try_pg_connect() -> Result<(), String> {
349	    let url = std::env::var("DATABASE_URL").map_err(|_| "DATABASE_URL not set".to_string())?;
350	
351	    let config = deadpool_postgres::Config {
352	        url: Some(url),
353	        ..Default::default()
354	    };
355	    let pool = crate::db::tls::create_pool(&config, crate::config::SslMode::from_env())
356	        .map_err(|e| format!("pool error: {e}"))?;
357	
358	    let client = tokio::time::timeout(std::time::Duration::from_secs(5), pool.get())
359	        .await
360	        .map_err(|_| "connection timeout (5s)".to_string())?
361	        .map_err(|e| format!("{e}"))?;
362	
363	    client
364	        .execute("SELECT 1", &[])
365	        .await
366	        .map_err(|e| format!("{e}"))?;
367	
368	    Ok(())
369	}
