408	                        && std::fs::read_to_string(&session_path)
409	                            .map(|s| !s.trim().is_empty())
410	                            .unwrap_or(false)
411	                }
412	                "ollama" => true, // local, no creds needed
413	                _ => config.openai_api_key().is_some(),
