485	async fn check_mcp_config() -> CheckResult {
486	    match crate::tools::mcp::config::load_mcp_servers().await {
487	        Ok(file) => {
488	            let servers: Vec<_> = file.enabled_servers().collect();
489	            if servers.is_empty() {
490	                return CheckResult::Skip("no MCP servers configured".into());
491	            }
492	
493	            let mut invalid = Vec::new();
494	            for server in &servers {
495	                if let Err(e) = server.validate() {
496	                    invalid.push(format!("{}: {}", server.name, e));
497	                }
498	            }
499	
500	            if invalid.is_empty() {
501	                CheckResult::Pass(format!("{} server(s) configured, all valid", servers.len()))
502	            } else {
503	                CheckResult::Fail(format!(
504	                    "{} server(s), {} invalid: {}",
505	                    servers.len(),
506	                    invalid.len(),
507	                    invalid.join("; ")
508	                ))
509	            }
510	        }
511	        Err(e) => {
512	            // Distinguish no config from corrupted config
513	            let msg = e.to_string();
514	            if msg.contains("not found") || msg.contains("No such file") {
515	                CheckResult::Skip("no MCP config file".into())
516	            } else {
517	                CheckResult::Fail(format!("config error: {e}"))
518	            }
519	        }
520	    }
