598	
599	fn check_binary(name: &str, args: &[&str]) -> CheckResult {
600	    match std::process::Command::new(name)
601	        .args(args)
602	        .stdout(std::process::Stdio::piped())
603	        .stderr(std::process::Stdio::piped())
604	        .output()
605	    {
606	        Ok(output) => {
607	            let version = String::from_utf8_lossy(&output.stdout);
608	            let version = version.trim();
609	            // Some tools print version to stderr
610	            let version = if version.is_empty() {
611	                let stderr = String::from_utf8_lossy(&output.stderr);
612	                stderr.trim().lines().next().unwrap_or("").to_string()
613	            } else {
614	                version.lines().next().unwrap_or("").to_string()
615	            };
616	
617	            if output.status.success() {
618	                CheckResult::Pass(version)
619	            } else {
620	                CheckResult::Fail(format!("exited with {}", output.status))
621	            }
622	        }
623	        Err(_) => CheckResult::Skip(format!("{name} not found in PATH")),
624	    }
625	}
