1	//! Unified HTTP server for all webhook routes.
2	//!
3	//! Composes route fragments from HttpChannel, WASM channel router, etc.
4	//! into a single axum server. Channels define routes but never spawn servers.
5	
6	use std::net::SocketAddr;
7	
8	use axum::Router;
9	use tokio::sync::oneshot;
10	use tokio::task::JoinHandle;
11	
12	use crate::error::ChannelError;
13	
14	/// Configuration for the unified webhook server.
15	pub struct WebhookServerConfig {
16	    /// Address to bind the server to.
17	    pub addr: SocketAddr,
18	}
19	
20	/// A single HTTP server that hosts all webhook routes.
21	///
22	/// Channels contribute route fragments via `add_routes()`, then a single
23	/// `start()` call binds the listener and spawns the server task.
24	pub struct WebhookServer {
25	    config: WebhookServerConfig,
26	    routes: Vec<Router>,
27	    /// Merged router saved after start() for restarts via `install_listener()`.
28	    merged_router: Option<Router>,
29	    shutdown_tx: Option<oneshot::Sender<()>>,
30	    handle: Option<JoinHandle<()>>,
31	}
32	
33	impl WebhookServer {
34	    /// Create a new webhook server with the given bind address.
35	    pub fn new(config: WebhookServerConfig) -> Self {
36	        Self {
37	            config,
38	            routes: Vec::new(),
39	            merged_router: None,
40	            shutdown_tx: None,
41	            handle: None,
42	        }
43	    }
44	
45	    /// Accumulate a route fragment. Each fragment should already have its
46	    /// state applied via `.with_state()`.
47	    pub fn add_routes(&mut self, router: Router) {
48	        self.routes.push(router);
49	    }
50	
51	    /// Bind the listener, merge all route fragments, and spawn the server.
52	    pub async fn start(&mut self) -> Result<(), ChannelError> {
53	        let mut app = Router::new();
54	        for fragment in self.routes.drain(..) {
55	            app = app.merge(fragment);
56	        }
57	        self.merged_router = Some(app.clone());
58	        self.bind_and_spawn(app).await
59	    }
60	
61	    /// Bind a listener to the configured address and spawn the server task.
62	    /// Private helper used by `start()`.
63	    async fn bind_and_spawn(&mut self, app: Router) -> Result<(), ChannelError> {
64	        let listener = tokio::net::TcpListener::bind(self.config.addr)
65	            .await
66	            .map_err(|e| ChannelError::StartupFailed {
67	                name: "webhook_server".to_string(),
68	                reason: format!("Failed to bind to {}: {}", self.config.addr, e),
69	            })?;
70	
71	        tracing::debug!("Webhook server listening on {}", self.config.addr);
72	
73	        let (shutdown_tx, shutdown_rx) = oneshot::channel();
74	        self.shutdown_tx = Some(shutdown_tx);
75	
76	        let handle = tokio::spawn(async move {
77	            if let Err(e) = axum::serve(listener, app)
78	                .with_graceful_shutdown(async {
79	                    let _ = shutdown_rx.await;
80	                    tracing::debug!("Webhook server shutting down");
81	                })
82	                .await
83	            {
84	                tracing::error!("Webhook server error: {}", e);
85	            }
86	        });
87	
88	        self.handle = Some(handle);
89	        Ok(())
90	    }
91	
92	    /// Clone the merged router, if `start()` has been called.
93	    pub fn merged_router_clone(&self) -> Option<Router> {
94	        self.merged_router.clone()
95	    }
96	
97	    /// Install a pre-bound listener, replacing the current one.
98	    ///
99	    /// The caller is responsible for binding the `TcpListener` *outside* any
100	    /// lock so that the async bind does not block other lock waiters. This
101	    /// method only does synchronous bookkeeping plus spawning the (non-blocking)
102	    /// server task, so it is safe to call while holding a mutex.
103	    pub fn install_listener(
104	        &mut self,
105	        new_addr: SocketAddr,
106	        listener: tokio::net::TcpListener,
107	        app: Router,
108	    ) -> (Option<oneshot::Sender<()>>, Option<JoinHandle<()>>) {
109	        // Capture old handles so the caller can shut them down outside the lock.
110	        let old_shutdown_tx = self.shutdown_tx.take();
111	        let old_handle = self.handle.take();
112	
113	        self.config.addr = new_addr;
114	
115	        // Spawn the new server task (non-blocking).
116	        let (shutdown_tx, shutdown_rx) = oneshot::channel();
117	        self.shutdown_tx = Some(shutdown_tx);
118	
119	        let handle = tokio::spawn(async move {
120	            if let Err(e) = axum::serve(listener, app)
121	                .with_graceful_shutdown(async {
122	                    let _ = shutdown_rx.await;
123	                    tracing::debug!("Webhook server shutting down");
124	                })
125	                .await
126	            {
127	                tracing::error!("Webhook server error: {}", e);
128	            }
129	        });
130	        self.handle = Some(handle);
131	
132	        tracing::debug!("Webhook server listening on {}", new_addr);
133	
134	        (old_shutdown_tx, old_handle)
135	    }
136	
137	    /// Return the current bind address.
138	    pub fn current_addr(&self) -> SocketAddr {
139	        self.config.addr
140	    }
141	
142	    /// Take ownership of shutdown primitives so callers can perform async
143	    /// shutdown work without holding external locks around this server.
144	    pub fn begin_shutdown(&mut self) -> (Option<oneshot::Sender<()>>, Option<JoinHandle<()>>) {
145	        (self.shutdown_tx.take(), self.handle.take())
146	    }
147	
148	    /// Signal graceful shutdown and wait for the server task to finish.
149	    pub async fn shutdown(&mut self) {
150	        let (shutdown_tx, handle) = self.begin_shutdown();
151	        if let Some(tx) = shutdown_tx {
152	            let _ = tx.send(());
153	        }
154	        if let Some(handle) = handle {
155	            let _ = handle.await;
156	        }
157	    }
158	}
